# ── Shared look & feel ────────────────────────────────────────────────────
# One theme, one palette, used by every module so all figures from the app
# belong to the same visual family.

theme_lab <- function(base_size = 16) {
  ggplot2::theme_classic(base_size = base_size) %+replace%
    ggplot2::theme(
      text         = ggplot2::element_text(family = "sans", colour = "black"),
      axis.line    = ggplot2::element_line(colour = "black", linewidth = 0.8),
      axis.ticks   = ggplot2::element_line(colour = "black", linewidth = 0.55),
      axis.title.x = ggplot2::element_text(size = base_size + 1, face = "bold",
                                           margin = ggplot2::margin(t = 10)),
      axis.title.y = ggplot2::element_text(size = base_size + 1, face = "bold",
                                           angle = 90, vjust = 0.5,
                                           margin = ggplot2::margin(r = 10)),
      axis.text    = ggplot2::element_text(size = base_size - 2, colour = "black"),
      plot.title   = ggplot2::element_text(size = base_size + 3, face = "bold",
                                           hjust = 0.5,
                                           margin = ggplot2::margin(b = 2)),
      plot.subtitle = ggplot2::element_text(size = base_size - 4, colour = "grey35",
                                            hjust = 0.5,
                                            margin = ggplot2::margin(b = 12)),
      legend.title = ggplot2::element_blank(),
      legend.text  = ggplot2::element_text(size = base_size - 3, face = "bold"),
      legend.position = "top",
      plot.margin  = ggplot2::margin(10, 16, 10, 12)
    )
}

# Colour-blind-safe defaults; grey first so controls/NTC land on grey.
PALETTES <- list(
  `Lab default` = c("#9B9B9B", "#D55E00", "#0072B2", "#009E73",
                    "#CC79A7", "#E69F00", "#56B4E9", "#3D405B"),
  Okabe_Ito     = c("#999999", "#E69F00", "#56B4E9", "#009E73",
                    "#F0E442", "#0072B2", "#D55E00", "#CC79A7"),
  Muted         = c("#AAAAAA", "#88CCEE", "#CC6677", "#DDCC77",
                    "#117733", "#332288", "#AA4499", "#44AA99"),
  Viridis       = c("#440154", "#46327E", "#365C8D", "#277F8E",
                    "#1FA187", "#4AC16D", "#A0DA39", "#FDE725")
)

pal_for <- function(groups, name = "Lab default") {
  p <- PALETTES[[name]] %||% PALETTES[[1]]
  stats::setNames(p[((seq_along(groups) - 1) %% length(p)) + 1], groups)
}

# p-value -> stars, the convention used in the lab's figures.
p_stars <- function(p) {
  ifelse(is.na(p), "",
  ifelse(p < 0.001, "***",
  ifelse(p < 0.01,  "**",
  ifelse(p < 0.05,  "*", "ns"))))
}

fmt_p <- function(p) {
  ifelse(is.na(p), NA_character_,
         ifelse(p < 1e-4, formatC(p, format = "e", digits = 2),
                formatC(p, format = "f", digits = 4)))
}

`%||%` <- function(a, b) if (is.null(a)) b else a

# TRUE when running inside webR/shinylive, where there is no shell, no system
# zip binary, and no cairo. Several helpers branch on this.
is_wasm <- function() {
  identical(R.version$os, "emscripten") ||
    grepl("emscripten", R.version$platform, fixed = TRUE)
}

# cairo_pdf gives nicer font handling, but it is absent in webR and on some
# macOS R builds it reports itself as available and then fails at draw time.
# Probe it once for real, cache the answer, fall back to the base PDF device.
pdf_device <- local({
  cached <- NULL
  function() {
    if (is.null(cached)) {
      ok <- FALSE
      if (!is_wasm()) {
        f  <- tempfile(fileext = ".pdf")
        ok <- tryCatch({
          grDevices::cairo_pdf(f); graphics::plot.new(); grDevices::dev.off()
          file.exists(f) && file.size(f) > 500
        }, warning = function(w) FALSE, error = function(e) FALSE)
        while (grDevices::dev.cur() > 1) try(grDevices::dev.off(), silent = TRUE)
        unlink(f)
      }
      cached <<- if (isTRUE(ok)) grDevices::cairo_pdf else grDevices::pdf
    }
    cached
  }
})

# PNG downloads use R's own png(). ragg would need textshaping, and the web
# build downloads every referenced package up front — a 13 MB Unicode library
# on every first visit for no visible difference.
png_device <- function() grDevices::png

# A colour picker using the browser's own <input type="color">. The
# colourpicker package did the same job but pulled in R Markdown, knitr and
# shinyjs — several megabytes of download for one widget.
colorInput <- function(inputId, label, value = "#000000") {
  div(class = "shiny-input-container mb-2",
      tags$label(class = "control-label small", `for` = inputId, label),
      tags$input(id = inputId, type = "color", value = value,
                 class = "lab-color form-control form-control-color w-100"))
}

COLOR_INPUT_JS <- "
$(function () {
  var b = new Shiny.InputBinding();
  $.extend(b, {
    find: function (scope) { return $(scope).find('input[type=color].lab-color'); },
    getValue: function (el) { return el.value; },
    setValue: function (el, v) { el.value = v; },
    subscribe: function (el, cb) { $(el).on('input.lab change.lab', function () { cb(true); }); },
    unsubscribe: function (el) { $(el).off('.lab'); },
    receiveMessage: function (el, d) { if (d.value) { el.value = d.value; $(el).trigger('change'); } }
  });
  Shiny.inputBindings.register(b, 'lab.color');
});"

# Downloads. Shiny opens each download in a new tab; in the web build that
# tab is answered by the shinylive service worker, and Chrome receives an
# empty page instead of the file (it saves "lda-freq_csv.html", then cancels).
# So every download button fetches its file from inside the app and saves it
# directly. Same files, same names, no new tab, no popup blocker.
DOWNLOAD_JS <- "
document.addEventListener('click', async function (e) {
  var a = e.target.closest && e.target.closest('a.shiny-download-link');
  if (!a) return;
  var href = a.getAttribute('href');
  if (!href || a.classList.contains('disabled')) return;
  e.preventDefault(); e.stopImmediatePropagation();
  if (a.dataset.busy) return;
  a.dataset.busy = '1'; a.classList.add('lab-busy');
  try {
    var r = await fetch(href, { credentials: 'same-origin' });
    if (!r.ok) throw new Error((await r.text()).slice(0, 300) || ('HTTP ' + r.status));
    var cd = r.headers.get('content-disposition') || '';
    var m = /filename\\*=UTF-8''([^;]+)/i.exec(cd) || /filename=\"?([^\";]+)\"?/i.exec(cd);
    var name = m ? decodeURIComponent(m[1]) : 'download';
    var url = URL.createObjectURL(await r.blob());
    var t = document.createElement('a');
    t.href = url; t.download = name; t.style.display = 'none';
    document.body.appendChild(t); t.click(); t.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
  } catch (err) {
    alert('That download failed: ' + err.message);
  } finally {
    delete a.dataset.busy; a.classList.remove('lab-busy');
  }
}, true);"

WIDE_JS <- "
$(function () {
  Shiny.addCustomMessageHandler('lab-wide', function (m) {
    var el = document.getElementById(m.id);
    if (!el) return;
    el.classList.toggle('lab-wide', !!m.wide);
    window.dispatchEvent(new Event('resize'));
  });
});"

# Plain HTML tables: numbers are already rounded, so print them as written.
as_display <- function(d) {
  d[] <- lapply(d, function(x) if (is.numeric(x)) as.character(x) else x)
  d
}

# ── Getting data in ───────────────────────────────────────────────────────
# One module handles data entry for every assay. The design rule here is that
# the person uploading should not have to know, or care, what shape their
# sheet is in. They press Upload. We work it out, say what we worked out, and
# let them correct us.

read_any <- function(path, name = path, sheet = 1) {
  ext <- tolower(tools::file_ext(name))
  if (ext %in% c("xlsx", "xls")) {
    validate(need(requireNamespace("readxl", quietly = TRUE),
                  "Excel files need the 'readxl' package. Save as .csv instead."))
    as.data.frame(readxl::read_excel(path, sheet = sheet))
  } else if (ext %in% c("tsv", "txt")) {
    utils::read.delim(path, stringsAsFactors = FALSE, check.names = FALSE)
  } else {
    utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
  }
}

# Excel copy-paste is tab-separated; a pasted CSV should work too.
read_pasted <- function(txt) {
  txt <- trimws(txt)
  if (!nzchar(txt)) return(NULL)
  sep <- if (grepl("\t", txt)) "\t" else if (grepl(";", txt)) ";" else ","
  utils::read.delim(text = txt, sep = sep, stringsAsFactors = FALSE,
                    check.names = FALSE)
}

# A column name means nothing on a sheet with no header row, so every picker
# shows what is actually in the column instead.
col_preview <- function(v, n = 4) {
  v <- v[!is.na(v) & trimws(as.character(v)) != ""]
  if (!length(v)) return("empty")
  txt <- paste(utils::head(trimws(as.character(v)), n), collapse = ", ")
  if (length(v) > n) txt <- paste0(txt, ", …")
  if (nchar(txt) > 42) txt <- paste0(substr(txt, 1, 40), "…")
  txt
}

looks_like_protocol <- function(df) {
  auto  <- sum(grepl("^\\.\\.\\.[0-9]+$|^X[0-9]+$", names(df)))
  blank <- sum(apply(df, 1, function(r)
    all(is.na(r) | trimws(as.character(r)) == "")))
  auto >= 2 || blank >= 1
}

# Fuzzy header matching: strip case, spaces, underscores, dots.
norm_name <- function(x) gsub("[^a-z0-9]", "", tolower(x))

# Aliases are in priority order: for cell counts, "cells counted" beats
# "cells seeded", because the count is what actually went into the well.
guess_col <- function(cols, aliases, exclude = character()) {
  n <- norm_name(cols); a <- norm_name(aliases)
  # An empty string matches everything under grepl(), so a sheet with blank
  # or auto-generated headers would otherwise "match" every field.
  ok <- nzchar(n) & !grepl("^[0-9]+$", n) & !cols %in% exclude
  a  <- unique(a[nzchar(a)])
  if (!any(ok) || !length(a)) return(NA_character_)
  for (al in a) {
    hit <- which(ok & n == al)
    if (length(hit)) return(cols[hit[1]])
  }
  # Partial matches only for aliases long enough to mean something — "n"
  # would otherwise match "condition".
  for (al in a[nchar(a) >= 3]) {
    hit <- which(ok & (grepl(al, n, fixed = TRUE) |
                       vapply(n, grepl, logical(1), x = al, fixed = TRUE)))
    if (length(hit)) return(cols[hit[1]])
  }
  NA_character_
}

# Guess every field at once, never giving one column to two fields.
guess_all <- function(cols, spec) {
  taken <- character()
  out <- list()
  for (k in names(spec)) {
    g <- guess_col(cols, c(k, spec[[k]]$aliases), exclude = taken)
    out[[k]] <- if (is.na(g)) "" else g
    if (!is.na(g)) taken <- c(taken, g)
  }
  out
}

required_fields <- function(spec)
  names(spec)[!vapply(spec, function(s) isTRUE(s$optional), logical(1))]

# ---- the module -----------------------------------------------------------
dataInputUI <- function(id, spec, example_label = "Example dataset",
                        protocol = FALSE) {
  ns <- NS(id)
  tagList(
    radioButtons(ns("src"), NULL, inline = TRUE,
                 choiceNames  = c(example_label, "Upload", "Paste"),
                 choiceValues = c("example", "file", "paste")),
    conditionalPanel(
      sprintf("input['%s'] == 'file'", ns("src")),
      fileInput(ns("file"), NULL, buttonLabel = "Choose file…",
                placeholder = "csv / tsv / xlsx",
                accept = c(".csv", ".tsv", ".txt", ".xlsx", ".xls")),
      uiOutput(ns("sheet_ui"))
    ),
    conditionalPanel(
      sprintf("input['%s'] == 'paste'", ns("src")),
      textAreaInput(ns("paste"), NULL, rows = 7,
                    placeholder = "Select the cells in Excel, copy, paste here."),
      div(class = "form-text mb-2",
          "Headers or no headers, any column order: the app works out which",
          " column is which from the numbers and tells you what it decided.")
    ),
    downloadLink(ns("template"), "Download a blank template / demo CSV"),
    uiOutput(ns("detected")),
    uiOutput(ns("preview")),
    uiOutput(ns("mapping")),
    uiOutput(ns("sanity")),
    uiOutput(ns("status"))
  )
}

dataInputServer <- function(id, spec, example, protocol = FALSE) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns
    req_fields <- required_fields(spec)

    output$sheet_ui <- renderUI({
      req(input$file)
      if (!tolower(tools::file_ext(input$file$name)) %in% c("xlsx", "xls"))
        return(NULL)
      sh <- tryCatch(readxl::excel_sheets(input$file$datapath),
                     error = function(e) NULL)
      if (length(sh) < 2) return(NULL)
      selectInput(ns("sheet"), "Sheet", choices = sh, selected = sh[1])
    })

    # ---- read the file both ways, then decide ---------------------------
    # Pasted text goes down exactly the same road as an uploaded file: it is
    # saved to a temporary file and read both ways. So whatever you paste —
    # with headers, without, in blocks — gets the same "work it out" logic.
    pasted <- debounce(reactive(input$paste), 600)
    source_file <- reactive({
      if (identical(input$src, "file")) {
        req(input$file)
        return(list(path = input$file$datapath, name = input$file$name))
      }
      txt <- pasted(); req(txt, nzchar(trimws(txt)))
      ext <- if (grepl("\t", txt)) "tsv" else "csv"
      if (!grepl("\t", txt) && grepl(";", txt)) { txt <- gsub(";", "\t", txt); ext <- "tsv" }
      f <- tempfile(fileext = paste0(".", ext))
      writeLines(txt, f)
      list(path = f, name = basename(f))
    })

    attempts <- reactive({
      src <- source_file()
      sh <- if (identical(input$src, "file")) input$sheet %||% 1 else 1
      list(
        plain = tryCatch(read_any(src$path, src$name, sh),
                         error = function(e) NULL),
        prot  = if (protocol)
          tryCatch(parse_protocol_file(src$path, src$name, sh),
                   error = function(e) NULL) else NULL)
    })

    # How many required fields can we name from the headers alone?
    n_guessed <- function(df) {
      if (is.null(df) || !ncol(df)) return(0L)
      g <- guess_all(names(df), spec)
      sum(vapply(req_fields, function(k) nzchar(g[[k]]), logical(1)))
    }

    auto_mode <- reactive({
      a <- attempts()
      if (!is.null(a$prot) && n_guessed(a$plain) < length(req_fields))
        "protocol" else "plain"
    })
    # "Use my header row" / "Work it out" is a choice about THIS data. New
    # data, new decision: forget the override whenever the input changes.
    override <- reactiveVal(NULL)
    observeEvent(source_file(), override(NULL))
    observeEvent(input$read_as, {
      a <- tryCatch(auto_mode(), error = function(e) NULL)
      override(if (identical(input$read_as, a)) NULL else input$read_as)
    }, ignoreInit = TRUE)
    read_mode <- reactive({
      if (identical(input$src, "example")) return("plain")
      override() %||% auto_mode()
    })

    # ---- tell them what we did, and let them overrule it ----------------
    output$detected <- renderUI({
      if (identical(input$src, "example")) return(NULL)
      a <- tryCatch(attempts(), error = function(e) NULL)
      if (is.null(a)) return(NULL)
      m <- read_mode()
      both <- !is.null(a$prot) && !is.null(a$plain)
      tagList(
        hr(),
        if (m == "protocol") div(
          class = "alert alert-success py-2 px-2 small mb-2",
          bsicons::bs_icon("magic"), strong(" Read as a lab sheet."),
          " No usable header row, so the columns were worked out from the",
          " numbers themselves — no naming needed.")
        else div(
          class = "alert alert-info py-2 px-2 small mb-2",
          bsicons::bs_icon("table"), strong(" Read as a plain table."),
          " The first row was used as the header."),
        if (both) radioButtons(
          ns("read_as"), NULL, inline = TRUE, selected = m,
          choiceNames  = c("Work it out from the numbers", "Use my header row"),
          choiceValues = c("protocol", "plain"))
      )
    })

    # ---- always show them their own data --------------------------------
    output$preview <- renderUI({
      d <- tryCatch(raw(), error = function(e) NULL)
      if (is.null(d) || !nrow(d)) return(NULL)
      div(class = "mb-2",
        div(class = "fw-bold small mb-1",
            sprintf("Your data (%d rows, showing first %d)", nrow(d), min(5, nrow(d)))),
        div(style = "overflow-x:auto; font-size:.75rem;",
            tableOutput(ns("preview_tbl"))))
    })
    output$preview_tbl <- renderTable({
      d <- tryCatch(raw(), error = function(e) NULL)
      req(d, nrow(d) > 0)
      show <- utils::head(as.data.frame(d), 5)
      show[] <- lapply(show, function(x) {
        x <- as.character(x); x[is.na(x)] <- ""; substr(x, 1, 16) })
      show
    }, striped = TRUE, spacing = "xs", width = "100%")

    # ---- raw table, exactly as supplied ---------------------------------
    raw <- reactive({
      switch(input$src,
        example = example,
        { a <- attempts()
          if (read_mode() == "protocol") a$prot else a$plain })
    })

    # Output that is already in our own shape needs no mapping step.
    canonical <- reactive(
      identical(input$src, "example") || identical(read_mode(), "protocol"))

    # ---- the mapping step, only when it is actually needed --------------
    output$mapping <- renderUI({
      df <- tryCatch(raw(), error = function(e) NULL)
      if (is.null(df) || !ncol(df) || canonical()) return(NULL)
      cols <- names(df)
      gs <- guess_all(cols, spec)
      tagList(
        div(class = "fw-bold mb-1", "Which column is which?"),
        div(class = "form-text mb-2",
            "Pick by the values, not the name — each option shows what is",
            " actually in that column."),
        lapply(names(spec), function(k) {
          s <- spec[[k]]
          guess <- gs[[k]]
          blank <- stats::setNames(
            "", if (isTRUE(s$optional)) "— none —" else "— choose —")
          shown <- stats::setNames(cols, vapply(cols, function(cn)
            sprintf("%s  —  %s", cn, col_preview(df[[cn]])), character(1)))
          selectInput(ns(paste0("map_", k)),
                      paste0(s$label, if (isTRUE(s$optional)) " (optional)" else ""),
                      choices  = c(blank, shown),
                      selected = guess)
        })
      )
    })

    # ---- catch an impossible mapping before it reaches the model --------
    # Organoids cannot exceed cells. If they do, offer to swap rather than
    # letting a model error surface three panels away.
    swap_pair <- reactive({
      if (canonical()) return(NULL)
      pairs <- list(c("Organoids", "CellCount"), c("Positive", "Tested"))
      for (pr in pairs) if (all(pr %in% names(spec))) return(pr)
      NULL
    })

    output$sanity <- renderUI({
      pr <- swap_pair(); if (is.null(pr)) return(NULL)
      df <- tryCatch(raw(), error = function(e) NULL); if (is.null(df)) return(NULL)
      pick <- function(k) {
        v <- input[[paste0("map_", k)]]
        if (!is.null(v)) return(v)
        guess_all(names(df), spec)[[k]]
      }
      a <- pick(pr[1]); b <- pick(pr[2])
      if (!nzchar(a) || !nzchar(b) || !a %in% names(df) || !b %in% names(df))
        return(NULL)
      ev <- suppressWarnings(as.numeric(df[[a]]))
      tr <- suppressWarnings(as.numeric(df[[b]]))
      bad <- sum(is.finite(ev) & is.finite(tr) & ev > tr)
      if (!bad) return(NULL)
      div(class = "alert alert-danger py-2 px-2 small",
          bsicons::bs_icon("exclamation-octagon-fill"),
          strong(sprintf(" '%s' is bigger than '%s' in %d rows.",
                         spec[[pr[1]]]$label, spec[[pr[2]]]$label, bad)),
          " That cannot happen, so these two are probably the wrong way round.",
          div(class = "mt-2",
              actionButton(ns("do_swap"), "Swap them", class = "btn-sm btn-danger")))
    })
    outputOptions(output, "sanity", suspendWhenHidden = FALSE)

    observeEvent(input$do_swap, {
      pr <- swap_pair(); req(pr)
      a <- input[[paste0("map_", pr[1])]]; b <- input[[paste0("map_", pr[2])]]
      updateSelectInput(session, paste0("map_", pr[1]), selected = b)
      updateSelectInput(session, paste0("map_", pr[2]), selected = a)
    })

    output$template <- downloadHandler(
      function() paste0(id, "_template.csv"),
      function(f) utils::write.csv(example, f, row.names = FALSE))

    # ---- canonical, type-coerced, validated -----------------------------
    tidy <- reactive({
      df <- raw()
      validate(need(!is.null(df) && nrow(df) > 0,
                    "No data yet — upload, paste, or use the example."))
      if (canonical()) {
        out <- df
      } else {
        out <- data.frame(row.names = seq_len(nrow(df)))
        for (k in names(spec)) {
          sel <- input[[paste0("map_", k)]]
          # Before the picker has rendered its input, use the guess directly,
          # so a well-formed file needs no round-trip and no empty flash.
          if (is.null(sel)) sel <- guess_all(names(df), spec)[[k]]
          if (!nzchar(sel)) {
            validate(need(isTRUE(spec[[k]]$optional),
                          sprintf("Still need to know which column holds '%s'.",
                                  spec[[k]]$label)))
            next
          }
          out[[k]] <- df[[sel]]
        }
      }
      for (k in intersect(names(spec), names(out))) {
        if (identical(spec[[k]]$type, "numeric")) {
          v <- suppressWarnings(as.numeric(gsub("[, ]", "", as.character(out[[k]]))))
          validate(need(!all(is.na(v)),
                        sprintf("'%s' has no numbers in it — wrong column?",
                                spec[[k]]$label)))
          out[[k]] <- v
        } else {
          out[[k]] <- trimws(as.character(out[[k]]))
        }
      }
      out <- out[stats::complete.cases(
        out[, intersect(names(spec), names(out)), drop = FALSE]), , drop = FALSE]
      validate(need(nrow(out) > 0, "Every row had a missing value after mapping."))
      out
    })

    output$status <- renderUI({
      df <- tryCatch(tidy(), error = function(e) NULL)
      if (is.null(df)) return(NULL)
      div(class = "alert alert-success py-1 px-2 mt-2 mb-0 small d-flex justify-content-between align-items-center",
          span(sprintf("%d rows ready.", nrow(df))),
          downloadLink(ns("dl_data"), tagList(bsicons::bs_icon("download"), " this data as CSV")))
    })
    outputOptions(output, "status", suspendWhenHidden = FALSE)

    output$dl_data <- downloadHandler(
      function() paste0(id, "_data.csv"),
      function(f) utils::write.csv(tidy(), f, row.names = FALSE))

    tidy
  })
}

# ── LDA statistics ────────────────────────────────────────────────────────
# Both common assay layouts reduce to ONE model: a binomial GLM with a
# complementary log-log link.
#
#   "cells"  every seeded cell is a trial, organoids are successes.
#            cloglog(p) = b            ->  frequency f = exp(b)   (per cell)
#
#   "wells"  every well is a trial, scored +/-, seeded with `Dose` cells.
#            p(+) = 1 - exp(-f * dose)
#            cloglog(p) = log(dose) + b  ->  same f = exp(b)
#            i.e. classic ELDA (Hu & Smyth 2009) written as an offset.
#
# So the fitting, the CIs and the group comparisons are shared code, and
# only the figure differs between the two layouts.

lda_fit <- function(df, groups, mode = c("cells", "wells"), conf = 0.95) {
  mode <- match.arg(mode)
  df <- df[df$Group %in% groups, , drop = FALSE]
  df$Group <- factor(df$Group, levels = groups)

  if (mode == "cells") {
    trials <- df$CellCount; events <- df$Organoids; off <- rep(0, nrow(df))
  } else {
    trials <- df$Tested;    events <- df$Positive;  off <- log(df$Dose)
  }
  bad <- which(is.finite(events) & is.finite(trials) & events > trials)
  if (length(bad)) {
    i <- bad[1]
    lab <- if (mode == "cells") c("Organoids formed", "Cells seeded")
           else                 c("Wells positive", "Wells tested")
    stop(sprintf(
      paste0("'%s' is bigger than '%s' in %d of %d rows.\n",
             "Row %d says %s grew from %s.\n",
             "Those two columns are almost certainly mapped the wrong way round."),
      lab[1], lab[2], length(bad), length(events),
      i, format(events[i]), format(trials[i])), call. = FALSE)
  }

  md  <- data.frame(events = events, fails = trials - events,
                    Group = droplevels(df$Group), off = off)
  # A single group has no contrasts to estimate — fit the intercept alone.
  form <- if (nlevels(md$Group) < 2) cbind(events, fails) ~ 1
          else                       cbind(events, fails) ~ Group
  fit <- stats::glm(stats::update(form, . ~ . + offset(off)),
                    family = stats::binomial(link = "cloglog"), data = md)

  b <- stats::coef(fit); V <- stats::vcov(fit); z <- stats::qnorm(1 - (1 - conf) / 2)

  est <- do.call(rbind, lapply(seq_along(groups), function(i) {
    L <- numeric(length(b)); L[1] <- 1; if (i > 1) L[i] <- 1
    e  <- sum(L * b)
    se <- sqrt(drop(t(L) %*% V %*% L))
    data.frame(Group = groups[i], n_rows = sum(df$Group == groups[i]),
               Frequency = exp(e), CI_low = exp(e - z * se), CI_high = exp(e + z * se),
               SE_log = se, stringsAsFactors = FALSE)
  }))
  est$`1 in` <- 1 / est$Frequency
  est$Group  <- factor(est$Group, levels = groups)

  # Goodness of fit: does a single frequency per group explain all doses?
  gof <- tryCatch(
    stats::pchisq(fit$deviance, fit$df.residual, lower.tail = FALSE),
    error = function(e) NA_real_)

  list(fit = fit, est = est, groups = groups, mode = mode,
       gof_p = gof, deviance = fit$deviance, df_resid = fit$df.residual)
}

# Wald test on any pair of groups, on the log-frequency scale.
lda_pairwise <- function(lda, pairs, adjust = "none") {
  if (!length(pairs)) return(NULL)
  b <- stats::coef(lda$fit); V <- stats::vcov(lda$fit); g <- lda$groups
  out <- do.call(rbind, lapply(pairs, function(pr) {
    i <- match(pr[1], g); j <- match(pr[2], g)
    # contrast is B - A, so Ratio reads as "B relative to A"
    L <- numeric(length(b)); if (j > 1) L[j] <- L[j] + 1; if (i > 1) L[i] <- L[i] - 1
    d  <- sum(L * b)                       # log fold-change in frequency
    se <- sqrt(drop(t(L) %*% V %*% L))
    zv <- d / se
    data.frame(A = pr[1], B = pr[2],
               Ratio = exp(d), CI_low = exp(d - 1.96 * se), CI_high = exp(d + 1.96 * se),
               z = zv, p = 2 * stats::pnorm(-abs(zv)), stringsAsFactors = FALSE)
  }))
  out$p_adj <- stats::p.adjust(out$p, method = adjust)
  out$stars <- p_stars(out$p_adj)
  out
}

# Observed per-row rate, used for the dots on the bar chart.
lda_observed <- function(df, mode = c("cells", "wells")) {
  mode <- match.arg(mode)
  if (mode == "cells") {
    data.frame(Group = df$Group, rate = df$Organoids / df$CellCount,
               stringsAsFactors = FALSE)
  } else {
    # per-dose MLE from the negative fraction: f = -log(1 - p+) / dose
    p <- pmin(df$Positive / df$Tested, 1 - 1e-9)
    data.frame(Group = df$Group, rate = -log(1 - p) / df$Dose,
               stringsAsFactors = FALSE)
  }
}

# Which group pairs to compare, shared by the app and the exported script.
# When the groups form panels (see group_panels), "vs ref" means "vs the
# reference treatment inside each panel" — N16-ATRA against N16-DMSO, never
# against Ad16-DMSO. "all" adds every pair inside a panel plus the same
# treatment across panels.
lda_pairs <- function(groups, ref, mode = c("none", "ref", "all"),
                      panels = group_panels(groups)) {
  mode <- match.arg(mode)
  if (length(groups) < 2 || is.null(ref) || !ref %in% groups) return(list())
  if (mode == "none") return(list())
  if (is.null(panels))
    return(switch(mode,
      ref = lapply(setdiff(groups, ref), function(x) c(ref, x)),
      all = utils::combn(groups, 2, simplify = FALSE)))

  ref_lab <- as.character(panels$Label[panels$Group == ref])
  out <- list()
  for (pn in levels(panels$Panel)) {
    in_p <- panels$Group[panels$Panel == pn]
    if (mode == "ref") {
      r <- in_p[as.character(panels$Label[panels$Panel == pn]) == ref_lab]
      r <- if (length(r)) r[1] else in_p[1]
      out <- c(out, lapply(setdiff(in_p, r), function(x) c(r, x)))
    } else if (length(in_p) >= 2) {
      out <- c(out, utils::combn(in_p, 2, simplify = FALSE))
    }
  }
  if (mode == "all")
    for (lb in levels(panels$Label)) {
      same <- panels$Group[panels$Label == lb]
      if (length(same) >= 2) out <- c(out, utils::combn(same, 2, simplify = FALSE))
    }
  out
}

